def _parse_ts(s: str) -> datetime:
    if s.endswith(("Z", "z")):
        s = s[:-1] + "+00:00"
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=timezone.utc)
    return d.astimezone(timezone.utc)


def _fmt_ts(d: datetime) -> str:
    return d.astimezone(timezone.utc).replace(microsecond=0).strftime("%Y-%m-%dT%H:%M:%SZ")


def _booking(b: dict[str, Any]) -> Booking:
    start = _parse_ts(b["starts_at"])
    end = _parse_ts(b["ends_at"])
    v4status = b["status"]
    cancellation = b.get("cancellation")
    if v4status == "expired":
        reason = "hold_expired"
    elif cancellation:
        reason = cancellation.get("reason")
    else:
        reason = None
    return Booking(
        id=b["id"],
        dock=b["dock_id"],
        start=start,
        duration_min=int((end - start).total_seconds() // 60),
        carrier=b["carrier"]["name"],
        carrier_scac=b["carrier"]["scac"],
        trailer=b.get("trailer_number"),
        status=_FROM_V4[v4status],
